# CP25 Step 3B reconstructed adjusted models and sensitivity analyses.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R")); rp_install_and_load(c("dplyr","readr","tibble","purrr")); source(file.path(sd_repo_root(),"R","panels","CP25","MANIFEST_RECONSTRUCTED.R"))
a<-sd_analysis_dir("CP25"); r<-file.path(a,"11_RData"); out<-file.path(a,"06_statistics"); sens<-file.path(a,"07_sensitivity"); dir.create(out,recursive=TRUE,showWarnings=FALSE); dir.create(sens,recursive=TRUE,showWarnings=FALSE)
load(file.path(r,"SDY2583_CP25_STEP3A_metadata_merge_age_QC_RECONSTRUCTED.RData")); mm<-CP25_MANIFEST$module_map
main_statistics<-rp_fit_feature_set(analysis_data,mm); binary_sex_statistics<-rp_fit_feature_set(analysis_data,mm,"binary_sex_only",TRUE); event_qc_statistics<-rp_fit_feature_set(analysis_data,mm,"primary_gate_ge300",FALSE,CP25_MANIFEST$primary_event_col,300)
readr::write_csv(main_statistics,file.path(out,"SDY2583_CP25_FULL850_age_sex_adjusted_statistics_MAIN_RECONSTRUCTED.csv")); readr::write_csv(main_statistics |> dplyr::filter(fdr_all<.05),file.path(out,"SDY2583_CP25_significant_global_FDR_0p05_MAIN_RECONSTRUCTED.csv")); readr::write_csv(main_statistics |> dplyr::filter(fdr_within_module<.05),file.path(out,"SDY2583_CP25_significant_module_FDR_0p05_MAIN_RECONSTRUCTED.csv")); readr::write_csv(binary_sex_statistics,file.path(sens,"SDY2583_CP25_binary_sex_sensitivity_statistics_RECONSTRUCTED.csv")); readr::write_csv(event_qc_statistics,file.path(sens,"SDY2583_CP25_event_QC_ge300_sensitivity_statistics_RECONSTRUCTED.csv")); save(main_statistics,binary_sex_statistics,event_qc_statistics,mm,file=file.path(r,"SDY2583_CP25_STEP3B_statistics_RECONSTRUCTED.RData")); cat("CP25 features:",nrow(main_statistics),"\n")
